import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TarUtils_parseOctal_TriageGen1Test {





    @Test
    public void testParseOctal_WithTrailingSpacesAndNulls() {
        byte[] buffer = "000123  \0\0".getBytes();
        // We need to ensure the buffer actually contains the null bytes for the logic to work
        byte[] extendedBuffer = new byte[10];
        System.arraycopy("000123  ".getBytes(), 0, extendedBuffer, 0, 8);
        // extendedBuffer[8] and [9] are already 0 by default in Java

        long result = TarUtils.parseOctal(extendedBuffer, 0, 10);
        assertEquals(83L, result);
    }














}

