public class TarUtils_parseOctal_TriageGen1Test {







    @Test
    public void testParseOctal_LeadingZeroByte() {
        byte[] buffer = new byte[5];
        buffer[0] = 0;
        buffer[1] = '0';
        buffer[2] = '1';
        // If buffer[start] == 0, it returns 0L immediately
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(0L, result);
    }












}

