package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TarUtils_parseOctal_TriageGen1Test {



















    @Test
    public void testParseOctal_MaxLongValue() {
        // Max octal that fits in long is roughly 17 odd digits
        // 77777777777777777 (17 sevens)
        byte[] buffer = "77777777777777777".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        // 7 * (8^16 + 8^15 ... + 8^0)
        long expected = 0;
        for (int i = 0; i < 17; i++) {
            expected = (expected << 3) + 7;
        }
        assertEquals(expected, result);
    }
}
